def clean_inline_markup(text: str) -> str:
    text = re.sub(r"^#{1,6}\s+", "", text.strip())
    text = re.sub(r"[*_`]", "", text)
    text = re.sub(r"\\([\[\]()>_.-])", r"\1", text)
    return re.sub(r"\s+", " ", text).strip().rstrip(":")


def normalize_mermaid(code: str) -> str:
    code = re.sub(r"\\([\[\](){}/_.|<>-])", r"\1", code)
    return code.replace("--\\>", "-->").replace("-.-\\>", "-.->")


def is_mermaid_statement(line: str) -> bool:
    value = line.strip()
    if not value:
        return True
    if value.startswith(
        (
            "flowchart ",
            "graph ",
            "block-beta",
            "columns ",
            "subgraph ",
            "direction ",
            "style ",
            "classDef ",
            "class ",
            "linkStyle ",
            "click ",
            "%%",
        )
    ):
        return True
    if value == "end":
        return True
    if value == "space" or re.fullmatch(
        r"[A-Za-z_][A-Za-z0-9_-]*\s*(?:\[[^\]]*\]|\([^)]*\)|\{\{.*\}\})(?::\d+)?",
        value,
    ):
        return True
    return any(token in value for token in ("-->", "--\\>", "-.->", "-.\\->", "==>"))


def replace_mermaid_blocks(
    text: str,
    visual_dir: str,
    *,
    apply_editorial_overrides: bool = False,
) -> tuple[str, list[dict[str, object]]]:
    lines = text.splitlines()
    output: list[str] = []
    manifest: list[dict[str, object]] = []
    index = 0
    i = 0

    while i < len(lines):
        if not re.match(r"^(?:(?:flowchart|graph)\s+|block-beta$)", lines[i].strip()):
            output.append(lines[i])
            i += 1
            continue

        start = i
        block: list[str] = []
        while i < len(lines) and is_mermaid_statement(lines[i]):
            block.append(lines[i])
            i += 1
        while block and not block[-1].strip():
            block.pop()

        index += 1
        previous = next((item for item in reversed(output) if item.strip()), "Схема")
        caption = clean_inline_markup(previous)
        if len(caption) > 180:
            caption = f"Схема управления агентом {index}"
        override = INLINE_DIAGRAM_OVERRIDES.get(index, {}) if apply_editorial_overrides else {}
        caption = str(override.get("caption", caption))
        mermaid = str(override.get("mermaid", normalize_mermaid("\n".join(block))))
        for old, new in MERMAID_TEXT_REPLACEMENTS.items():
            mermaid = mermaid.replace(old, new)
        filename = f"ru-inline-diagram-{index:02d}.png"
        image_line = f"![{caption}]({visual_dir}/{filename})"
        output.extend([image_line, ""])
        manifest.append(
            {
                "number": index,
                "transformed_line": start + 1,
                "caption": caption,
                "filename": filename,
                "markdown_image": image_line,
                "raw_text": "\n".join(block),
                "mermaid": mermaid,
            }
        )

    if index != 29:
        raise ValueError(f"Expected 29 Mermaid blocks, found {index}")
    return "\n".join(output).rstrip() + "\n", manifest


def normalize_numbered_figures(text: str, visual_dir: str) -> str:
    pattern = re.compile(
        r"^Рисунок (?P<number>\d+)\\?\.\s+[^\n]+\n\n"
        r"!\[[^\n]*\](?:\([^)]+\)|\[image\d+\])$",
        re.MULTILINE,
    )
    seen: list[int] = []

    def replacement(match: re.Match[str]) -> str:
        number = int(match.group("number"))
        if number not in NUMBERED_FIGURES:
            raise ValueError(f"Unknown numbered figure: {number}")
        title, alt_text, filename = NUMBERED_FIGURES[number]
        seen.append(number)
        return f"![{alt_text}]({visual_dir}/{filename})\n\nРисунок {number}. {title}"

    text = pattern.sub(replacement, text)
    if seen != list(range(1, 26)):
        raise ValueError(f"Unexpected numbered figure mapping: {seen}")

    lines = [line for line in text.splitlines() if re.match(r"^\[image\d+\]:", line) is None]
    text = "\n".join(lines).rstrip() + "\n"
    if "data:image/" in text or "![][image" in text:
        raise ValueError("Embedded or unresolved numbered figure remains in manuscript")
    return text


def replace_front_matter_and_introduction(text: str) -> str:
    author_marker = "## Об авторе"
    intro_marker = "## Введение. Зачем эта книга нужна"
    body_marker = "# Часть I. От демо-агента к платформе"

    if author_marker not in text or intro_marker not in text or body_marker not in text:
        raise ValueError("Required front-matter markers are missing")

    author_start = text.index(author_marker)
    intro_start = text.index(intro_marker)
    body_start = text.index(body_marker)
    title = text.splitlines()[0].strip()
    author_block = text[author_start:intro_start].strip()
    return f"{title}\n\n{author_block}\n\n{INTRODUCTION.strip()}\n\n{text[body_start:]}"


def normalize_headings(text: str) -> str:
    output: list[str] = []
    for line in text.splitlines():
        if re.fullmatch(r"#{1,6}\s*(?:\*+)?\s*", line):
            continue

        exercise = re.fullmatch(r"#\s+\*\*Практическое упражнение части (.+?)\*\*", line)
        if exercise:
            output.append(f"## Практическое упражнение части {exercise.group(1)}")
            continue

        conclusion = re.fullmatch(r"#\s+\*\*(Заключение\..+?)\*\*", line)
        if conclusion:
            output.append(f"# {conclusion.group(1)}")
            continue

        heading = re.fullmatch(r"(#{1,6})\s+(.+)", line)
        if heading:
            title = clean_inline_markup(heading.group(2))
            if title in GENERIC_HEADINGS:
                label = (
                    "Связь со следующей главой" if title == "Переход к следующей теме" else title
                )
                output.append(
                    f"**{label}.**" if label == "Связь со следующей главой" else f"**{label}**"
                )
                continue
            if title == "Мост зрелости":
                output.append("### Мост зрелости")
                continue
            if title == "Три сценария после полного маршрута":
                output.append("## Три сценария после полного маршрута")
                continue

        output.append(line)
    return "\n".join(output).rstrip() + "\n"


def remove_near_duplicate_blocks(text: str) -> str:
    blocks = re.split(r"(\n\s*\n)", text)
    seen_cross_references: set[str] = set()
    result: list[str] = []

    for block in blocks:
        if re.fullmatch(r"\n\s*\n", block):
            result.append(block)
            continue
        normalized = clean_inline_markup(block)
        words = normalized.split()
        previous_content = next(
            (
                clean_inline_markup(item)
                for item in reversed(result)
                if not re.fullmatch(r"\n\s*\n", item) and item.strip()
            ),
            "",
        )
        is_cross_reference = (
            previous_content != "Читать дальше"
            and len(words) >= 12
            and block.lstrip().startswith("*")
            and block.count("* Глава") >= 2
        )
        if is_cross_reference and normalized in seen_cross_references:
            continue
        result.append(block)
        if is_cross_reference:
            seen_cross_references.add(normalized)
    return "".join(result)


def link_source_list(text: str) -> str:
    pattern = re.compile(r"^(\*\s+)([^\n\[]+?)\s+\((https://[^)]+)\)\s*$", re.MULTILINE)

    def replacement(match: re.Match[str]) -> str:
        label = match.group(2).strip()
        if label.startswith("OpenReview,"):
            label = label.replace("OpenReview,", "OpenReview (препринт),", 1)
        return f"{match.group(1)}[{label}]({match.group(3)}), дата обращения: 15 июля 2026 года."

    return pattern.sub(replacement, text)


def prune_irrelevant_source_sections(text: str) -> str:
    return replace_between(
        text,
        "### Публикация, сборка и платформенный слой книги",
        "### Как использовать этот список",
        "",
    )


def insert_telemetry_clarification(text: str) -> str:
    anchor = (
        "Этот пример нарочно простой. Его задача не заменить SDK трассировки, "
        "а показать принцип: каждый важный шаг должен оставлять после себя "
        "структурированный след."
    )
    addition = (
        "\n\nСтатус спана и исход операции нельзя смешивать. Если обертка вызова "
        "завершилась без исключения, но инструмент вернул структурированный "
        "результат `failed`, спан не должен выглядеть как успешное действие. "
        "Либо его `status` отражает итог операции, либо событие дополнительно "
        "несет `operation_status` и `result_class`. Иначе расследование увидит "
        "зеленый спан внутри неуспешного запуска и потеряет причину отказа."
    )
    if anchor not in text:
        raise ValueError("Telemetry clarification anchor is missing")
    return text.replace(anchor, anchor + addition, 1)


def condense_dense_reference_paragraphs(text: str) -> str:
    output: list[str] = []
    replaced: set[str] = set()

    def comparison_text(value: str) -> str:
        return clean_inline_markup(re.sub(r"\\(.)", r"\1", value))

    for line in text.splitlines():
        normalized = comparison_text(line)
        replacement = next(
            (
                value
                for prefix, value in DENSE_PARAGRAPH_REPLACEMENTS.items()
                if normalized.startswith(comparison_text(prefix))
            ),
            None,
        )
        if replacement is None:
            output.append(line)
            continue

        prefix = next(
            prefix
            for prefix in DENSE_PARAGRAPH_REPLACEMENTS
            if normalized.startswith(comparison_text(prefix))
        )
        replaced.add(prefix)
        output.extend(replacement.splitlines())

    missing = set(DENSE_PARAGRAPH_REPLACEMENTS) - replaced
    if missing:
        raise ValueError(f"Dense reference paragraphs are missing: {sorted(missing)}")
    return "\n".join(output).rstrip() + "\n"


def replace_between(text: str, start: str, end: str, replacement: str) -> str:
    start_index = text.find(start)
    if start_index < 0:
        raise ValueError(f"Start marker is missing: {start}")
    end_index = text.find(end, start_index + len(start))
    if end_index < 0:
        raise ValueError(f"End marker is missing after {start}: {end}")
    return text[:start_index] + replacement.rstrip() + "\n\n" + text[end_index:]


def remove_overloaded_reference_sections(text: str) -> str:
    text = replace_between(
        text,
        "Этот раздел собирает в одном месте минимальный контрактный слой для артефактов жизненного цикла",
        "## Глава 6\\. Инструментальный шлюз, подтверждения и журнал аудита",
        "",
    )
    text = replace_between(
        text,
        "### Что должно существовать всегда",
        "## Практическое упражнение части VI",
        "",
    )
    return text


def insert_part_openers(text: str) -> str:
    for heading, opener in PART_OPENERS.items():
        if heading not in text:
            raise ValueError(f"Part heading is missing: {heading}")
        text = text.replace(heading, f"{heading}\n\n{opener}", 1)
    return text


def insert_part_conclusions(text: str) -> str:
    for marker, conclusions in PART_CONCLUSIONS.items():
        if marker not in text:
            raise ValueError(f"Part exercise marker is missing: {marker}")
        bullets = "\n".join(f"* {item}" for item in conclusions)
        text = text.replace(
            marker,
            f"## Выводы части\n\n{bullets}\n\n{marker}",
            1,
        )
    return text


def remove_repeated_editorial_scaffolding(text: str) -> str:
    prefixes = (
        "Заметка о сквозных сценариях",
        "Канонические сценарии",
        "Канонические маршруты сценариев",
        "Что запомнить:",
        "Типичные ошибки:",
        "Что проверить в своей системе:",
        "Сопутствующие материалы:",
        "Переход к следующей теме:",
        "Если на несколько вопросов подряд ответ",
    )
    output: list[str] = []
    for line in text.splitlines():
        if line.strip().startswith(prefixes):
            continue
        output.append(line)
    return "\n".join(output).rstrip() + "\n"


def restore_incident_playbook_intro(text: str) -> str:
    marker = "### Что считать инцидентом"
    if marker not in text:
        raise ValueError("Incident playbook marker is missing")
    if "Рисунок 19\\. Контур реагирования на инцидент агента" in text:
        return text

    intro = r"""Этот практический маршрут нужен, когда у команды уже есть трассы,
шлюзы политик, цепочки подтверждения и правила поэтапного выпуска, но еще нет
короткой рабочей формы для реакции на сбой, опасное действие или обход
ограничений. Он не заменяет наблюдаемость, заверение и управление изменениями,
а собирает их в последовательность оперативных действий.

Рисунок 19\. Контур реагирования на инцидент агента

![][image19]

Неизвестный внешний эффект блокирует слепой повтор; все этапы опираются на одну
полосу связанных доказательств."""
    return text.replace(marker, f"{intro}\n\n{marker}", 1)


def label_technical_examples(text: str) -> str:
    replacements = {
        "Простой кодовый каркас": "Псевдокод",
        "Простой кодовый пример": "Псевдокод",
        "Кодовый эскиз:": "Псевдокод:",
        "Пример политики для": "Конфигурация (YAML):",
        "Пример политики ": "Конфигурация (YAML): ",
        "Пример контракта политики": "Конфигурация: контракт политики",
        "Пример контракта каталога возможностей": "Конфигурация: контракт каталога возможностей",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return text


def _pseudo_table_cells(line: str) -> list[str]:
    return [value.strip() for value in line.strip().strip("|").split("|")]


def _consume_pseudo_table(lines: list[str], start_index: int) -> tuple[list[str], int]:
    table = [lines[start_index]]
    index = start_index + 1
    while index < len(lines):
        if not lines[index].strip():
            lookahead = index + 1
            while lookahead < len(lines) and not lines[lookahead].strip():
                lookahead += 1
            if lookahead < len(lines) and lines[lookahead].strip().startswith("|"):
                index = lookahead
                continue
            break
        if not lines[index].strip().startswith("|"):
            break
        table.append(lines[index])
        index += 1
    return table, index


def convert_pseudo_tables_to_lists(text: str) -> str:
    lines = text.splitlines()
    output: list[str] = []
    converted = 0
    index = 0
    target_headers = {"Ситуация", "Угроза", "Поле каталога", "Вопрос", "Event type"}

    while index < len(lines):
        if (
            not lines[index].strip().startswith("|")
            or _pseudo_table_cells(lines[index])[0] not in target_headers
        ):
            output.append(lines[index])
            index += 1
            continue

        table, index = _consume_pseudo_table(lines, index)

        headers = _pseudo_table_cells(table[0])
        separator = _pseudo_table_cells(table[1])
        if (
            len(headers) < 2
            or len(separator) != len(headers)
            or not all(re.fullmatch(r"\\?:?-{3,}:?", value) for value in separator)
        ):
            output.extend(table)
            continue

        converted += 1
        event_table = headers[0] == "Event type"
        labels = {
            "Event type": "Тип события",
            "Когда появляется": "Когда",
            "Зачем нужен": "Назначение",
        }
        headers = [labels.get(header, header) for header in headers]
        for row in table[2:]:
            values = [
                value.replace(r"\_", "_").replace(r"\-", "-") for value in _pseudo_table_cells(row)
            ]
            if len(values) != len(headers):
                raise ValueError(f"Malformed pseudo-table row: {row}")
            lead = f"`{values[0]}`" if event_table else f"**{values[0].rstrip('.')}**"
            details = "; ".join(
                f"{header.lower()}: {value}" for header, value in zip(headers[1:], values[1:])
            )
            output.append(f"* {lead} — {details.rstrip('.')}.")
        output.append("")

    if converted != 5:
        raise ValueError(f"Expected 5 pseudo-tables, converted {converted}")
    return "\n".join(output).rstrip() + "\n"


def insert_figure_references(text: str) -> str:
    caption_pattern = re.compile(r"^Рисунок (\d+)\\?\.\s+(.+)$")
    lines = text.splitlines()
    reference_by_image_line: dict[int, str] = {}
    referenced: list[int] = []

    for caption_index, line in enumerate(lines):
        match = caption_pattern.match(line)
        if match is None:
            continue
        image_index = next(
            (index for index in range(caption_index - 1, -1, -1) if lines[index].strip()),
            None,
        )
        if image_index is None or not lines[image_index].startswith("!["):
            raise ValueError(f"Figure caption is not below an image: {line}")
        number = int(match.group(1))
        title = match.group(2).strip().rstrip(".")
        reference_by_image_line[image_index] = f"На рисунке {number} представлена схема «{title}»."
        referenced.append(number)

    if referenced != list(range(1, 26)):
        raise ValueError(f"Unexpected numbered figures: {referenced}")

    output: list[str] = []
    for index, line in enumerate(lines):
        if index in reference_by_image_line:
            output.extend([reference_by_image_line[index], ""])
        output.append(line)
    return "\n".join(output).rstrip() + "\n"


def _code_line_key(line: str) -> str:
    unescaped = re.sub(r"\\([^A-Za-zА-Яа-я0-9\s])", r"\1", line)
    return re.sub(r"[^A-Za-zА-Яа-я0-9]+", "", unescaped).lower()


def _source_listing(source_path: Path, key: str) -> str:
    source = source_path.read_text(encoding="utf-8")
    matches = [
        match.group(2).strip("\n")
        for match in re.finditer(r"```([^\n]*)\n(.*?)\n```", source, re.DOTALL)
        if key in match.group(2)
    ]
    if len(matches) != 1:
        raise ValueError(
            f"Expected one source listing containing {key!r} in {source_path}, found {len(matches)}"
        )
    return matches[0]


def _degraded_fragment_bounds(
    lines: list[str],
    key_index: int,
    verified_keys: set[str],
) -> tuple[int, int]:
    start = key_index
    while start > 0:
        previous = lines[start - 1]
        if not previous.strip() or _code_line_key(previous) in verified_keys:
            start -= 1
            continue
        break
    while start < key_index and not lines[start].strip():
        start += 1

    end = key_index
    cursor = key_index + 1
    while cursor < len(lines):
        candidate = lines[cursor]
        if not candidate.strip() or _code_line_key(candidate) in verified_keys:
            if candidate.strip():
                end = cursor
            cursor += 1
            continue
        break
    return start, end


def _fragment_key_coverage(fragment: list[str], verified_keys: set[str]) -> float:
    restored_keys = {_code_line_key(line) for line in fragment if line.strip()}
    return len(restored_keys & verified_keys) / max(1, len(verified_keys))


def restore_verified_python_listings(text: str) -> str:
    repo_root = Path(__file__).resolve().parents[3]
    listing_number = 0

    for key, relative_source, caption in LISTING_SPECS:
        source_path = repo_root / relative_source
        code = _source_listing(source_path, key)
        match_source = LEGACY_LISTING_MATCH_SOURCES.get(key, code)
        code_keys = {_code_line_key(line) for line in match_source.splitlines() if line.strip()}
        key_token = _code_line_key(key)
        lines = text.splitlines()

        inside_fence = False
        candidates: list[int] = []
        for index, line in enumerate(lines):
            if line.startswith("```"):
                inside_fence = not inside_fence
                continue
            if not inside_fence and key_token in _code_line_key(line):
                candidates.append(index)
        if len(candidates) != 1:
            raise ValueError(
                f"Expected one degraded listing containing {key!r}, found {len(candidates)}"
            )

        key_index = candidates[0]
        start, end = _degraded_fragment_bounds(lines, key_index, code_keys)
        coverage = _fragment_key_coverage(lines[start : end + 1], code_keys)
        if coverage < 0.7:
            raise ValueError(f"Listing {key!r} matched only {coverage:.0%} of its verified source")

        listing_number += 1
        label = (
            f"**Листинг {listing_number}. {caption}.** Тип: синтаксически проверяемый "
            f"учебный пример; источник: `{relative_source}`."
        )
        replacement = [label, "", "```python", *code.splitlines(), "```"]
        lines[start : end + 1] = replacement
        text = "\n".join(lines).rstrip() + "\n"

    return text


def _structured_fence_language(raw_language: str, block: str) -> str | None:
    language = raw_language.strip().lower()
    if language in {"mermaid", "python", "pseudocode"}:
        return None
    if re.search(r"(?m)^(?:class |def |async def |@dataclass)", block):
        return None
    if language in {"yaml", "yml", "json", "console", "bash", "shell"}:
        return "yaml" if language == "yml" else language

    non_empty = [line.strip() for line in block.splitlines() if line.strip()]
    if not non_empty:
        return None
    if non_empty[0].startswith(("{", "[")) and non_empty[-1].endswith(("}", "]")):
        return "json"
    command_prefixes = (
        "uv ",
        "git ",
        "python ",
        "pytest ",
        "ruff ",
        "ty ",
        "mkdir ",
        "curl ",
        "$ ",
    )
    if all(line.startswith(command_prefixes) for line in non_empty):
        return "console"
    yaml_like = sum(
        bool(re.match(r"^(?:-\s+)?[A-Za-z_][A-Za-z0-9_.-]*\s*:", line)) or line.startswith("- ")
        for line in non_empty
    )
    if len(non_empty) >= 3 and yaml_like / len(non_empty) >= 0.45:
        return "yaml"
    return None


def _collect_structured_source_blocks(book_root: Path) -> list[tuple[str, str]]:
    source_blocks: list[tuple[str, str]] = []
    seen_blocks: set[str] = set()
    for source_path in sorted(book_root.rglob("*.md")):
        if source_path.name.endswith((".en.md", ".zh.md")):
            continue
        source = source_path.read_text(encoding="utf-8")
        for match in re.finditer(r"```([^\n]*)\n(.*?)\n```", source, re.DOTALL):
            block = match.group(2).strip("\n")
            language = _structured_fence_language(match.group(1), block)
            if language is None or block in seen_blocks:
                continue
            seen_blocks.add(block)
            source_blocks.append((language, block))

    source_blocks.sort(key=lambda item: len(item[1]), reverse=True)
    return source_blocks


def _index_unfenced_lines_by_key(lines: list[str]) -> dict[str, list[int]]:
    inside_fence = False
    outside_by_key: dict[str, list[int]] = {}
    for index, line in enumerate(lines):
        if line.startswith("```"):
            inside_fence = not inside_fence
            continue
        if inside_fence or not line.strip():
            continue
        outside_by_key.setdefault(_code_line_key(line), []).append(index)
    return outside_by_key


def _select_unique_structured_anchor(
    unique_keys: set[str],
    outside_by_key: dict[str, list[int]],
) -> int | None:
    for key in sorted(unique_keys, key=len, reverse=True):
        candidates = outside_by_key.get(key, [])
        if len(key) >= 12 and len(candidates) == 1:
            return candidates[0]
    return None


def _restore_structured_block(text: str, language: str, block: str) -> tuple[str, bool]:
    match_block = next(
        (legacy for marker, legacy in LEGACY_STRUCTURED_MATCH_SOURCES.items() if marker in block),
        block,
    )
    block_keys = [_code_line_key(line) for line in match_block.splitlines() if line.strip()]
    unique_keys = set(block_keys)
    if len(unique_keys) < 2:
        return text, False

    lines = text.splitlines()
    outside_by_key = _index_unfenced_lines_by_key(lines)
    anchor_index = _select_unique_structured_anchor(unique_keys, outside_by_key)
    if anchor_index is None:
        return text, False

    start, end = _degraded_fragment_bounds(lines, anchor_index, unique_keys)
    coverage = _fragment_key_coverage(lines[start : end + 1], unique_keys)
    if coverage < 0.7:
        return text, False

    lines[start : end + 1] = [f"```{language}", *block.splitlines(), "```"]
    return "\n".join(lines).rstrip() + "\n", True


def restore_structured_book_blocks(text: str) -> str:
    repo_root = Path(__file__).resolve().parents[3]
    book_root = repo_root / "docs/book"
    source_blocks = _collect_structured_source_blocks(book_root)
    restored = 0
    for language, block in source_blocks:
        text, block_restored = _restore_structured_block(text, language, block)
        if block_restored:
            restored += 1

    if restored < 25:
        raise ValueError(f"Expected to restore at least 25 structured blocks, found {restored}")
    return text


