def apply_compaction_continuity_pass_2026_07_21(text: str) -> str:
    """Make context compaction a fail-closed, executable continuity contract."""
    capability_old = """В длинных запусках полезно различать сжатие и сброс контекста. Артефакт передачи после сброса является недоверенным производным описанием и не переносит полномочия. Идентификаторы и отпечатки подтверждения, версии политик и возможностей, делегирование и отзыв, `idempotency_key`, `side_effect_status`, бюджеты, состояние песочницы и пользовательские ограничения переносятся отдельно и без суммаризации; следующий шаг заново авторизуется средой исполнения."""
    capability_new = r"""В длинных запусках необходимо различать два слоя. **Представление контекста** — сообщения, извлеченные фрагменты и их сокращенная сводка — можно сжимать или пересобирать. **Управляющее состояние** — идентичность и область делегирования, версии политик и возможностей, подтверждения, бюджеты, состояние песочницы и сведения о побочных эффектах — хранится долговечно вне контекста модели. Сводка после сжатия является недоверенным производным описанием: она помогает восстановить ход рассуждения, но не переносит полномочия и не служит доказательством того, что действие разрешено.

Граница между слоями задается явным конвертом непрерывности. Без суммаризации в нем сохраняются `policy_version`, `capability_version`, `approval_id`, отпечаток одобренного действия `action_digest`, срок действия подтверждения, `idempotency_key`, `side_effect_status`, `checkpoint_ref`, идентичность принципала и цепочка делегирования, остаток бюджета, профиль песочницы, точные ограничения и обязательства политики. Отдельно записываются отпечаток сводки `summary_sha256` и происхождение событий трассы. Такой конверт не является новым токеном доступа: после восстановления среда исполнения обязана заново проверить каждый его элемент и заново авторизовать следующий шаг.

Безопасный протокол сжатия состоит из пяти переходов.

**Шаг 1. Зафиксировать исполнение.** До сжатия среда исполнения останавливает выдачу новых действий, дожидается завершения известных операций и сохраняет контрольную точку в управляемом хранилище.

**Шаг 2. Создать недоверенную сводку.** Среда исполнения формирует ее только для восстановления рабочего контекста, вычисляет отпечаток и пишет событие `context_compaction` со ссылкой на контрольную точку.

**Шаг 3. Восстановить управляющее состояние.** После сброса новый процесс загружает его из доверенного хранилища и проверяет отпечаток сводки, идентичность, делегирование, версии политик и возможностей, подтверждения, бюджеты и ограничения.

**Шаг 4. Закрыть неоднозначность.** Расхождение любого из этих полей приводит к `continuity_validation_failed`. Неизвестный результат операции приводит к `blocked_on_reconciliation`: сначала нужно сверить фактический побочный эффект по `idempotency_key`, а не повторять действие вслепую.

**Шаг 5. Заново авторизовать продолжение.** Только после успешной проверки среда исполнения пересобирает контекст, пишет `context_rehydration` и запускает обычную авторизацию заново. Успешная проверка непрерывности доказывает целостность перехода, но сама по себе не разрешает действие.

Этот контракт следует проверять парными сценариями оценки на полной и сокращенной истории. При одинаковом долговечном состоянии решения должны совпадать. Подмена сводки, смена версии политики или возможности, истекшее либо отозванное подтверждение и дрейф области делегирования должны завершаться запретом. Неизвестный побочный эффект должен блокировать продолжение до сверки. Так потеря деталей разговора превращается из скрытой особенности модели в наблюдаемый переход состояния с проверяемой семантикой отказа."""
    text = _replace_editorial_anchor(
        text,
        capability_old,
        capability_new,
        "chapter 5 compaction continuity contract",
    )

    appendix_old = """Для длинной работы те же связи переживают сброс контекста и передачу роли через структурированный артефакт. Эталон показывает места таких контрактов, но не реализует промышленный долговечный исполнитель."""
    appendix_new = r"""Для длинной работы те же связи переживают сжатие и сброс контекста через `ContinuityEnvelope`. Эталон намеренно остается учебным, но позволяет выполнить и проверить главный защитный инвариант: сводка не переносит полномочия, а восстановленное действие всегда требует новой авторизации среды исполнения.

```console
uv run python -m agent_runtime_ref inspect-continuity
uv run python -m agent_runtime_ref inspect-continuity --tamper-summary
uv run python -m agent_runtime_ref inspect-continuity \
  --current-policy-version policy-v5
uv run python -m agent_runtime_ref inspect-continuity \
  --side-effect-status side_effect_unknown
```

Первый запуск проверяет целостный конверт и заканчивается решением `reauthorization_required`: восстановление прошло успешно, но действие еще не разрешено. Второй обнаруживает несовпадение `summary_sha256`, третий — дрейф версии политики; оба записывают `continuity_validation_failed` и закрывают продолжение. Четвертый возвращает `blocked_on_reconciliation`: прежде чем повторять действие, исполнитель должен установить его фактический результат по ключу идемпотентности. Во всех четырех случаях поле `authorized` остается ложным.

Используйте эти команды как минимальную лабораторную работу, а не как промышленное хранилище контрольных точек. В рабочей системе конверт должен читаться из управляемого долговечного хранилища, быть связан с журналом событий и решением политики, защищаться от отката версии и проверяться до того, как модель снова увидит инструменты с побочными эффектами."""
    return _replace_editorial_anchor(
        text,
        appendix_old,
        appendix_new,
        "reference appendix compaction continuity lab",
    )


