def apply_final_publisher_copyedit_2026_07_22(text: str) -> str:
    replacements_path = (
        Path(__file__).resolve().parents[1] / "ru-final-copyedit-replacements-2026-07-22.json"
    )
    payload = json.loads(replacements_path.read_text(encoding="utf-8"))
    if payload.get("schema_version") != 1:
        raise ValueError("unsupported final copyedit replacement schema")

    for item in payload["replacements"]:
        old = item["old"]
        occurrences = text.count(old)
        if occurrences != 1:
            raise ValueError(f"{item['id']}: expected one source fragment, found {occurrences}")
        text = text.replace(old, item["new"], 1)

    return text


def _replace_legacy_or_validate_current(
    text: str,
    old: str,
    current: str,
    label: str,
    *,
    old_label: str | None = None,
) -> str:
    if old in text:
        return _replace_editorial_anchor(text, old, current, old_label or label)
    if text.count(current) != 1:
        raise ValueError(f"Current {label} must occur exactly once")
    return text


def _replace_three_state_editorial_anchor(
    text: str,
    oldest: str,
    intermediate: str,
    current: str,
    label: str,
    *,
    oldest_label: str | None = None,
    intermediate_label: str | None = None,
    current_error: str | None = None,
) -> str:
    if oldest in text:
        return _replace_editorial_anchor(text, oldest, current, oldest_label or label)
    if intermediate in text:
        return _replace_editorial_anchor(
            text,
            intermediate,
            current,
            intermediate_label or label,
        )
    if text.count(current) != 1:
        raise ValueError(current_error or f"Current {label} must occur exactly once")
    return text


def _insert_once_unless_marker(
    text: str,
    anchor: str,
    replacement: str,
    marker: str,
    label: str,
    *,
    anchor_label: str | None = None,
) -> str:
    if marker not in text:
        return _replace_editorial_anchor(
            text,
            anchor,
            replacement,
            anchor_label or label,
        )
    if text.count(marker) != 1:
        raise ValueError(f"Current {label} must occur once")
    return text


