def _label_heading_adjacent_fences(text: str) -> str:
    lines = text.splitlines()
    output: list[str] = []
    inside_fence = False
    index = 0
    while index < len(lines):
        line = lines[index]
        if line.startswith("```"):
            inside_fence = not inside_fence
            output.append(line)
            index += 1
            continue
        if not inside_fence and re.match(r"^#{1,6} ", line):
            cursor = index + 1
            while cursor < len(lines) and not lines[cursor].strip():
                cursor += 1
            if cursor < len(lines) and lines[cursor].startswith("```"):
                lead = (
                    "Выполните команду и сохраните результат:"
                    if "Шаг " in line
                    else "**Тип фрагмента:** минимальный контракт."
                )
                output.extend([line, "", lead, ""])
                index = cursor
                continue
        output.append(line)
        index += 1
    text = "\n".join(output).rstrip() + "\n"

    return text


def _repair_world_class_listing_layout(text: str) -> str:
    text = text.replace(
        '        return ToolResult(status="validation_failure", payload={"reason": "missing idempotency key"})',
        "        return ToolResult(\n"
        '            status="validation_failure",\n'
        '            payload={"reason": "missing idempotency key"},\n'
        "        )",
    )
    text = text.replace(
        "Просмотр одной трассы из JSONL-файла:\n\n```console",
        "Просмотр одной трассы из JSONL-файла:\n\n"
        "**Тип фрагмента:** команда для воспроизведения.\n\n```console",
    )

    return text


def _wrap_world_class_shell_lines(text: str) -> str:
    lines = text.splitlines()
    output: list[str] = []
    fence_language = ""
    for line in lines:
        if line.startswith("```"):
            fence_language = "" if fence_language else line[3:].strip().lower()
            output.append(line)
            continue
        if fence_language in {"console", "bash", "shell"} and len(line) > 100:
            tokens = re.findall(r'"(?:\\.|[^"\\])*"|\S+', line)
            current = ""
            wrapped: list[str] = []
            for token in tokens:
                candidate = token if not current else f"{current} {token}"
                if current and len(candidate) > 96:
                    wrapped.append(f"{current} \\")
                    current = f"  {token}"
                else:
                    current = candidate
            if current:
                wrapped.append(current)
            output.extend(wrapped)
        else:
            output.append(line)

    return "\n".join(output).rstrip() + "\n"


def apply_world_class_technical_edit_2026_07_23(text: str) -> str:
    """Apply structural and source-discipline fixes required for print."""
    text = _apply_required_world_class_replacements(text)
    text = _normalize_create_ticket_risk(text)
    text = _strengthen_approval_chain(text)
    text = _extend_case_and_chapter_sources(text)
    text = _insert_stacked_heading_bridges(text)
    text = _label_heading_adjacent_fences(text)
    text = _repair_world_class_listing_layout(text)
