    def make_run_in(match: re.Match[str]) -> str:
        label = match.group("label")
        if not re.search(r"[.:?!]$", label):
            label += "."
        return f"**{label}** {match.group('body')}"

    text = run_in_pattern.sub(make_run_in, text)
